import React, { useState, useEffect } from 'react';
import axios from 'axios';

const OrdersDisplay = () => {
    const [orders, setOrders] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    // Fetch orders from backend
    const fetchOrders = async () => {
        try {
            const response = await axios.get('http://localhost:5000/orders');
            setOrders(response.data.data || []);
            setLoading(false);
        } catch (err) {
            setError('Failed to fetch orders');
            setLoading(false);
        }
    };

    // Delete order functionality
    const handleDeleteOrder = async (orderId) => {
        try {
            await axios.delete(`http://localhost:5000/orders/${orderId}`);
            // Refresh orders after deletion
            fetchOrders();
        } catch (err) {
            alert('Failed to delete order');
        }
    };

    // Trigger initial fetch
    useEffect(() => {
        fetchOrders();
    }, []);

    // Render loading state
    if (loading) {
        return <div>Loading orders...</div>;
    }

    // Render error state
    if (error) {
        return <div>{error}</div>;
    }

    return (
        <div className="container mx-auto p-4">
            <h1 className="text-2xl font-bold mb-4">Orders Management</h1>
            
            {orders.length === 0 ? (
                <p>No orders found.</p>
            ) : (
                <div className="overflow-x-auto">
                    <table className="w-full border-collapse">
                        <thead>
                            <tr className="bg-gray-200">
                                <th className="border p-2">Order ID</th>
                                <th className="border p-2">Name</th>
                                <th className="border p-2">Email</th>
                                <th className="border p-2">Phone</th>
                                <th className="border p-2">Address</th>
                                <th className="border p-2">City</th>
                                <th className="border p-2">Pickup Time</th>
                                <th className="border p-2">Status</th>
                                <th className="border p-2">Actions</th>
                            </tr>
                        </thead>
                        <tbody>
                            {orders.map((order) => (
                                <tr key={order._id} className="hover:bg-gray-100">
                                    <td className="border p-2">{order.orderId}</td>
                                    <td className="border p-2">{order.firstName} {order.lastName}</td>
                                    <td className="border p-2">{order.email}</td>
                                    <td className="border p-2">{order.phoneNumber}</td>
                                    <td className="border p-2">{order.address}</td>
                                    <td className="border p-2">{order.city}</td>
                                    <td className="border p-2">{order.pickupTime}</td>
                                    <td className="border p-2">
                                        <span 
                                            className={`px-2 py-1 rounded ${
                                                order.orderStatus === 'Completed' 
                                                    ? 'bg-green-200 text-green-800' 
                                                    : order.orderStatus === 'Pending' 
                                                    ? 'bg-yellow-200 text-yellow-800' 
                                                    : 'bg-red-200 text-red-800'
                                            }`}
                                        >
                                            {order.orderStatus}
                                        </span>
                                    </td>
                                    <td className="border p-2">
                                        <div className="flex space-x-2">
                                            <button 
                                                onClick={() => handleDeleteOrder(order._id)}
                                                className="bg-red-500 text-white px-2 py-1 rounded hover:bg-red-600"
                                            >
                                                Delete
                                            </button>
                                            <button 
                                                className="bg-blue-500 text-white px-2 py-1 rounded hover:bg-blue-600"
                                            >
                                                Edit
                                            </button>
                                        </div>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            )}
        </div>
    );
};

export default OrdersDisplay;
